{
  "definitions": {
    "items": {
      "properties": {
        "id": {
          "type": "string",
          "format": "uuid",
          "title": "Id",
          "default": "<uuid>"
        },
        "key": {
          "type": "string",
          "maxLength": 64,
          "minLength": 1,
          "pattern": "^[a-z][a-z0-9_]*$",
          "title": "Key",
          "description": "Lowercase slug used as metric key (e.g. 'voice_quality_score')"
        },
        "name": {
          "type": "string",
          "maxLength": 256,
          "minLength": 1,
          "default": "<string>"
        },
        "description": {
          "type": "string",
          "maxLength": 2000,
          "default": "<string>"
        },
        "metric_type": {
          "type": "string",
          "enum": [
            "numerical",
            "categorical",
            "boolean"
          ],
          "title": "Metric Type"
        },
        "latency_tier": {
          "type": "string",
          "enum": [
            "streaming",
            "near_realtime",
            "batch"
          ],
          "title": "Latency Tier",
          "description": "'streaming' — seconds-latency via ZeroBus streaming ingestion (continuous pipeline). 'near_realtime' — minutes-latency via triggered pipeline refresh. 'batch' — hourly/daily scheduled refresh (default, cheapest).",
          "default": "batch"
        },
        "period_granularity": {
          "type": "string",
          "enum": [
            "hourly",
            "daily"
          ],
          "title": "Period Granularity",
          "description": "'hourly' — one row per workspace per hour. Use for near_realtime metrics where shift-level visibility matters (voice quality, latency). 'daily' — one row per workspace per day (default, cheapest).",
          "default": "daily"
        },
        "source": {
          "type": "string",
          "enum": [
            "call_intelligence",
            "world_events",
            "surface_events",
            "emotion_events",
            "connector_events",
            "zerobus_events",
            "voice_judge_results",
            "custom"
          ],
          "title": "Source",
          "description": "Source key for the producer that supplies this metric. Built-ins include 'call_intelligence', 'world_events', and 'surface_events'. Use 'custom' with custom_source_key for extension producers."
        },
        "custom_source_key": {
          "type": "string",
          "maxLength": 128,
          "minLength": 1,
          "pattern": "^[a-z][a-z0-9_]*$"
        },
        "event_types": {
          "items": {
            "type": "string",
            "default": "<string>"
          },
          "type": "array",
          "maxItems": 100,
          "minItems": 1,
          "title": "Event Types",
          "description": "Event types to scan (e.g. 'call.outcome', 'surface.submitted'). For call_intelligence source, use pseudo-types: 'call_intelligence.row'."
        },
        "source_filter": {
          "type": "string",
          "default": "<string>"
        },
        "extraction_mode": {
          "type": "string",
          "enum": [
            "static",
            "ai_classify",
            "ai_extract",
            "ai_query",
            "sql_expr"
          ],
          "title": "Extraction Mode",
          "description": "'static' — JSONB path extraction (fast, free). 'ai_classify' — AI classification into user-defined labels (free). 'ai_extract' — AI field extraction from text (free). 'ai_query' — LLM-powered extraction with custom prompt (uses model_tier). 'sql_expr' — Raw SQL expression for computed metrics.",
          "default": "static"
        },
        "extract_path": {
          "type": "string",
          "default": "<string>"
        },
        "ai_labels": {
          "items": {
            "type": "string",
            "default": "<string>"
          },
          "type": "array",
          "maxItems": 500
        },
        "ai_schema": {
          "additionalProperties": true,
          "type": "object",
          "properties": {}
        },
        "ai_query_endpoint": {
          "type": "string",
          "maxLength": 256,
          "default": "<string>"
        },
        "ai_query_prompt": {
          "type": "string",
          "maxLength": 8000,
          "default": "<string>"
        },
        "sql_expression": {
          "type": "string",
          "maxLength": 1000,
          "default": "<string>"
        },
        "aggregation": {
          "type": "string",
          "enum": [
            "count",
            "sum",
            "avg",
            "min",
            "max",
            "count_distinct",
            "ratio",
            "rate"
          ],
          "title": "Aggregation",
          "description": "How to aggregate extracted values per workspace per period. 'ratio' requires ratio_numerator_event and ratio_denominator_event. 'rate' computes count(true) / count(all) for boolean metrics.",
          "default": "count"
        },
        "ratio_numerator_event": {
          "type": "string",
          "default": "<string>"
        },
        "ratio_denominator_event": {
          "type": "string",
          "default": "<string>"
        },
        "valid_range_min": {
          "type": "number",
          "default": "<number>"
        },
        "valid_range_max": {
          "type": "number",
          "default": "<number>"
        },
        "freshness_sla_minutes": {
          "type": "integer",
          "maximum": 1440,
          "minimum": 5,
          "title": "Freshness Sla Minutes",
          "description": "Max acceptable staleness in minutes before alerting. Default: 60 (1 hour).",
          "default": 60
        },
        "unit": {
          "type": "string",
          "maxLength": 32,
          "default": "<string>"
        },
        "categories": {
          "items": {
            "type": "string",
            "default": "<string>"
          },
          "type": "array",
          "maxItems": 100
        },
        "model_tier": {
          "type": "string",
          "enum": [
            "free",
            "fast",
            "balanced",
            "max",
            "custom"
          ],
          "title": "Model Tier",
          "description": "AI model tier for extraction quality/cost tradeoff. 'free' — platform managed models (ai_classify, ai_extract). 'fast' — optimized for simple classification, low latency. 'balanced' — quality scoring, moderate reasoning. 'max' — complex analysis, multi-step reasoning. 'custom' — use ai_query_endpoint directly. When extraction_mode='ai_query' and ai_query_endpoint is not set, platform resolves model_tier to the optimal model automatically.",
          "default": "free"
        },
        "channel_scope": {
          "type": "string",
          "enum": [
            "all",
            "voice",
            "text",
            "surface",
            "inbound",
            "outbound"
          ],
          "title": "Channel Scope",
          "description": "Business-logic channel filter. 'voice' — voice calls only. 'text' — SMS/text sessions. 'surface' — form submissions. 'inbound'/'outbound' — by direction. 'all' — no channel filter (default). Pipeline translates to appropriate source + event_type filters.",
          "default": "all"
        },
        "applies_to_product_types": {
          "items": {
            "type": "string",
            "default": "<string>"
          },
          "type": "array"
        },
        "prompt": {
          "type": "string",
          "maxLength": 4000,
          "default": "<string>"
        },
        "granularity": {
          "type": "string",
          "enum": [
            "aggregate",
            "per_entity"
          ],
          "title": "Granularity",
          "description": "'aggregate' groups by (workspace, period) — one value per time bucket. 'per_entity' keeps entity_id — one value per entity (call, encounter). Judge metrics are typically per_entity. Computed metrics are typically aggregate.",
          "default": "aggregate"
        },
        "active": {
          "type": "boolean",
          "title": "Active",
          "default": true
        },
        "builtin": {
          "type": "boolean",
          "title": "Builtin",
          "description": "True for platform-provided metrics (read-only key).",
          "default": false
        }
      },
      "type": "object",
      "required": [
        "key",
        "name",
        "metric_type",
        "source",
        "event_types"
      ],
      "title": "MetricDefinition",
      "description": "A single metric definition — what to extract and how.\n\nTwo broad modes:\n- Built-in metrics: extraction is handled by hardcoded pipeline logic\n  (extract_path + aggregation). Shipped with every workspace.\n- Custom metrics: extraction uses AI functions or static JSONB paths.\n  Defined per-workspace via settings API.\n\nFrozen: builtins are process-wide singletons exposed via the\n``BUILTIN_METRICS`` list. A mutable list field (e.g.\n``applies_to_product_types``) could otherwise be mutated by one caller\nand leak into every subsequent call in the same process."
    },
    "type": "array",
    "title": "Definitions"
  }
}

